/* eslint-disable space-in-parens */

/// <reference types="@stdlib/types"/>

import zeros = require( '@stdlib/ndarray/zeros' );
import copyWithin = require( './index' );


// TESTS //

// The function returns an ndarray...
{
	copyWithin( zeros( [ 2, 2 ], { 'dtype': 'float64' } ), 2, 0 ); // $ExpectType float64ndarray
	copyWithin( zeros( [ 2, 2 ], { 'dtype': 'float64' } ), 2, 0, {} ); // $ExpectType float64ndarray
	copyWithin( zeros( [ 2, 2 ], { 'dtype': 'float64' } ), 2, 0, 4 ); // $ExpectType float64ndarray
	copyWithin( zeros( [ 2, 2 ], { 'dtype': 'float64' } ), 2, 0, 4, {} ); // $ExpectType float64ndarray
	copyWithin( zeros( [ 2, 2 ], { 'dtype': 'float32' } ), 2, 0 ); // $ExpectType float32ndarray
	copyWithin( zeros( [ 2, 2 ], { 'dtype': 'float32' } ), 2, 0, {} ); // $ExpectType float32ndarray
	copyWithin( zeros( [ 2, 2 ], { 'dtype': 'int32' } ), 2, 0 ); // $ExpectType int32ndarray
	copyWithin( zeros( [ 2, 2 ], { 'dtype': 'int32' } ), 2, 0, {} ); // $ExpectType int32ndarray
	copyWithin( zeros( [ 2, 2 ], { 'dtype': 'complex128' } ), 2, 0 ); // $ExpectType complex128ndarray
	copyWithin( zeros( [ 2, 2 ], { 'dtype': 'complex128' } ), 2, 0, {} ); // $ExpectType complex128ndarray
	copyWithin( zeros( [ 2, 2 ], { 'dtype': 'complex64' } ), 2, 0 ); // $ExpectType complex64ndarray
	copyWithin( zeros( [ 2, 2 ], { 'dtype': 'complex64' } ), 2, 0, {} ); // $ExpectType complex64ndarray
	copyWithin( zeros( [ 2, 2 ], { 'dtype': 'generic' } ), 2, 0 ); // $ExpectType genericndarray<number>
	copyWithin( zeros( [ 2, 2 ], { 'dtype': 'generic' } ), 2, 0, {} ); // $ExpectType genericndarray<number>
}

// The function returns an ndarray when provided ndarray index arguments...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});

	copyWithin( x, x, x ); // $ExpectType float64ndarray
	copyWithin( x, x, x, {} ); // $ExpectType float64ndarray
	copyWithin( x, x, x, x ); // $ExpectType float64ndarray
	copyWithin( x, x, x, x, {} ); // $ExpectType float64ndarray
}

// The compiler throws an error if the function is provided a first argument which is not an ndarray...
{
	copyWithin( '5', 2, 0 ); // $ExpectError
	copyWithin( 5, 2, 0 ); // $ExpectError
	copyWithin( true, 2, 0 ); // $ExpectError
	copyWithin( false, 2, 0 ); // $ExpectError
	copyWithin( null, 2, 0 ); // $ExpectError
	copyWithin( void 0, 2, 0 ); // $ExpectError
	copyWithin( {}, 2, 0 ); // $ExpectError
	copyWithin( ( x: number ): number => x, 2, 0 ); // $ExpectError

	copyWithin( '5', 2, 0, {} ); // $ExpectError
	copyWithin( 5, 2, 0, {} ); // $ExpectError
	copyWithin( true, 2, 0, {} ); // $ExpectError
	copyWithin( false, 2, 0, {} ); // $ExpectError
	copyWithin( null, 2, 0, {} ); // $ExpectError
	copyWithin( void 0, 2, 0, {} ); // $ExpectError
	copyWithin( {}, 2, 0, {} ); // $ExpectError
	copyWithin( ( x: number ): number => x, 2, 0, {} ); // $ExpectError
}

// The compiler throws an error if the function is provided a target index argument which is not an ndarray or integer...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});

	copyWithin( x, '5', 0 ); // $ExpectError
	copyWithin( x, true, 0 ); // $ExpectError
	copyWithin( x, false, 0 ); // $ExpectError
	copyWithin( x, null, 0 ); // $ExpectError
	copyWithin( x, [], 0 ); // $ExpectError
	copyWithin( x, ( x: number ): number => x, 0 ); // $ExpectError

	copyWithin( x, '5', 0, {} ); // $ExpectError
	copyWithin( x, true, 0, {} ); // $ExpectError
	copyWithin( x, false, 0, {} ); // $ExpectError
	copyWithin( x, null, 0, {} ); // $ExpectError
	copyWithin( x, [], 0, {} ); // $ExpectError
	copyWithin( x, ( x: number ): number => x, 0, {} ); // $ExpectError
}

// The compiler throws an error if the function is provided a start index argument which is not an ndarray or integer...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});

	copyWithin( x, 2, '5' ); // $ExpectError
	copyWithin( x, 2, true ); // $ExpectError
	copyWithin( x, 2, false ); // $ExpectError
	copyWithin( x, 2, null ); // $ExpectError
	copyWithin( x, 2, [] ); // $ExpectError
	copyWithin( x, 2, ( x: number ): number => x ); // $ExpectError

	copyWithin( x, 2, '5', {} ); // $ExpectError
	copyWithin( x, 2, true, {} ); // $ExpectError
	copyWithin( x, 2, false, {} ); // $ExpectError
	copyWithin( x, 2, null, {} ); // $ExpectError
	copyWithin( x, 2, [], {} ); // $ExpectError
	copyWithin( x, 2, ( x: number ): number => x, {} ); // $ExpectError
}

// The compiler throws an error if the function is provided an end index argument which is not an ndarray or integer...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});

	copyWithin( x, 2, 0, '5', {} ); // $ExpectError
	copyWithin( x, 2, 0, true, {} ); // $ExpectError
	copyWithin( x, 2, 0, false, {} ); // $ExpectError
	copyWithin( x, 2, 0, null, {} ); // $ExpectError
	copyWithin( x, 2, 0, [], {} ); // $ExpectError
	copyWithin( x, 2, 0, ( x: number ): number => x, {} ); // $ExpectError
}

// The compiler throws an error if the function is provided an options argument which is not an object...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});

	copyWithin( x, 2, 0, '5' ); // $ExpectError
	copyWithin( x, 2, 0, true ); // $ExpectError
	copyWithin( x, 2, 0, false ); // $ExpectError
	copyWithin( x, 2, 0, null ); // $ExpectError
	copyWithin( x, 2, 0, [] ); // $ExpectError
	copyWithin( x, 2, 0, ( x: number ): number => x ); // $ExpectError

	copyWithin( x, 2, 0, 4, '5' ); // $ExpectError
	copyWithin( x, 2, 0, 4, true ); // $ExpectError
	copyWithin( x, 2, 0, 4, false ); // $ExpectError
	copyWithin( x, 2, 0, 4, null ); // $ExpectError
	copyWithin( x, 2, 0, 4, [] ); // $ExpectError
	copyWithin( x, 2, 0, 4, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an invalid `dims` option...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});

	copyWithin( x, 2, 0, { 'dims': '5' } ); // $ExpectError
	copyWithin( x, 2, 0, { 'dims': 5 } ); // $ExpectError
	copyWithin( x, 2, 0, { 'dims': true } ); // $ExpectError
	copyWithin( x, 2, 0, { 'dims': false } ); // $ExpectError
	copyWithin( x, 2, 0, { 'dims': null } ); // $ExpectError
	copyWithin( x, 2, 0, { 'dims': {} } ); // $ExpectError
	copyWithin( x, 2, 0, { 'dims': ( x: number ): number => x } ); // $ExpectError

	copyWithin( x, 2, 0, 4, { 'dims': '5' } ); // $ExpectError
	copyWithin( x, 2, 0, 4, { 'dims': 5 } ); // $ExpectError
	copyWithin( x, 2, 0, 4, { 'dims': true } ); // $ExpectError
	copyWithin( x, 2, 0, 4, { 'dims': false } ); // $ExpectError
	copyWithin( x, 2, 0, 4, { 'dims': null } ); // $ExpectError
	copyWithin( x, 2, 0, 4, { 'dims': {} } ); // $ExpectError
	copyWithin( x, 2, 0, 4, { 'dims': ( x: number ): number => x } ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});

	copyWithin(); // $ExpectError
	copyWithin( x ); // $ExpectError
	copyWithin( x, 2 ); // $ExpectError
	copyWithin( x, 2, 0, 4, {}, {} ); // $ExpectError
}
